update public.learning_paths
set
  title = 'Photojournalism',
  goal = 'Photojournalism',
  summary = 'A core undergraduate journalism course in visual reporting, camera operation, composition, lighting, breaking-news coverage, portraits, sports/action, mobile workflow, editing and toning, captions, visual ethics, verification, picture stories, accessibility, and professional portfolio development.',
  data = $phojjson${"slug": "photojournalism", "title": "Photojournalism", "description": "A core undergraduate journalism course in visual reporting, camera operation, composition, lighting, breaking-news coverage, portraits, sports/action, mobile workflow, editing and toning, captions, visual ethics, verification, picture stories, accessibility, and professional portfolio development.", "topics": [{"id": "d6828b0b-954f-457b-a4d1-dda7586b59f4", "type": "topic", "title": "Camera Operation and Exposure", "description": "Photojournalists need technical control fast enough to disappear into the reporting. This section gives students command of camera settings so they can respond to real events without missing decisive moments.", "children": [{"id": "3026ef86-0aab-4793-ba95-ca7ace8e85c2", "type": "subtopic", "title": "Exposure triangle", "children": [{"id": "2ef6a3b8-85a2-42c9-aaeb-dedb3649cbf2", "type": "concept", "title": "Aperture"}, {"id": "f7b083fb-489c-498a-957b-b8ab54cb1618", "type": "concept", "title": "Shutter speed"}, {"id": "8877c47d-2bc5-4591-b76b-14138068e25d", "type": "concept", "title": "ISO"}, {"id": "eb342c79-f4b2-41c1-a71e-d87b07fe5c31", "type": "concept", "title": "Exposure compensation"}], "description": "Students learn how aperture, shutter speed, and ISO work together to shape brightness, motion, depth, and noise."}, {"id": "472a9c2f-d805-457f-8ec4-fdbfc083d183", "type": "subtopic", "title": "Focus and capture modes", "children": [{"id": "7ca9223a-ce43-4e4d-8013-bc1ed43ee74a", "type": "concept", "title": "Autofocus modes"}, {"id": "67e6caf9-a4d3-4613-9e22-82a36308a06a", "type": "concept", "title": "Focus points"}, {"id": "bacbf81e-7346-443b-80c2-0575b5e97f58", "type": "concept", "title": "Burst mode"}, {"id": "1da75edf-5bcc-46f6-8aa8-89665d635625", "type": "concept", "title": "Silent shooting"}], "description": "The point is to choose reliable settings for moving subjects, quiet moments, and unpredictable news scenes."}, {"id": "44e1a9a0-89cc-4665-a25e-466ab83283dc", "type": "subtopic", "title": "File formats and camera setup", "children": [{"id": "278f2b8b-dd53-4187-b41a-a356c4e76ffd", "type": "concept", "title": "RAW vs. JPEG"}, {"id": "b81cdfb9-9a91-4fe5-9807-ecd55d4d661a", "type": "concept", "title": "White balance"}, {"id": "15b3ae11-f5e8-4390-94e8-c221112608ff", "type": "concept", "title": "Dual-card backup"}, {"id": "9232b7bc-25f5-488f-9a2c-650e8ebbd3cd", "type": "concept", "title": "Time and date settings"}], "description": "Students learn to configure cameras for professional editing, transmission, and archive workflows."}]}, {"id": "61c780ef-308b-4a26-8eaf-725972338e63", "type": "topic", "title": "Composition for News Photos", "description": "Composition in photojournalism is not just beauty; it is clarity, evidence, hierarchy, and meaning. Students learn to organize the frame so audiences understand what matters and why.", "children": [{"id": "4ff47f43-2e3e-4f55-90b5-19b5676a920a", "type": "subtopic", "title": "Visual hierarchy", "children": [{"id": "3121efa1-532c-48f6-84c3-217be2876dc2", "type": "concept", "title": "Foreground/background"}, {"id": "b5e75d78-d60e-4fb6-be51-2f9a9e317aae", "type": "concept", "title": "Layering"}, {"id": "2f7ed1ba-6a6d-404a-b282-90343bff02f5", "type": "concept", "title": "Leading lines"}, {"id": "996fc873-6f8c-4764-b3d7-23843e914dad", "type": "concept", "title": "Point of emphasis"}], "description": "Students learn how framing directs attention and clarifies the news value of an image."}, {"id": "d0b7e4d4-c12e-4ed6-8537-ee6740f48c7c", "type": "subtopic", "title": "Moment and gesture", "children": [{"id": "7dfd36a0-87dd-46a4-bf0e-856ea4cb9ced", "type": "concept", "title": "Decisive moment"}, {"id": "c2d3b46d-f986-4c74-a2de-adb521f713d1", "type": "concept", "title": "Body language"}, {"id": "13c9aa94-4bf1-4f28-bb44-652b92bdd026", "type": "concept", "title": "Facial expression"}, {"id": "36de677d-f4b2-4d6e-a22b-0ff74b76fa8f", "type": "concept", "title": "Repetition and contrast"}], "description": "Students practice recognizing action, emotion, interaction, and symbolic detail as they unfold."}, {"id": "26f24dfb-c4ee-48e1-aa4a-ae0d8147a9a3", "type": "subtopic", "title": "Context in the frame", "children": [{"id": "bbf23aeb-d96e-496e-a14c-f176008099fe", "type": "concept", "title": "Establishing context"}, {"id": "4459e13c-eda7-47be-b6f4-b17359616f18", "type": "concept", "title": "Scale"}, {"id": "e13e8668-33f1-4745-8214-3d646d104d20", "type": "concept", "title": "Place cues"}, {"id": "7ecf9c9e-156a-40b1-a2bd-ac8e203ff7ba", "type": "concept", "title": "Relevant details"}], "description": "The goal is to include enough environment, evidence, and relationship to avoid isolated or misleading pictures."}]}, {"id": "c94afe97-89c5-4d2c-bc6e-7659586af611", "type": "topic", "title": "Light, Color, and Visual Quality", "description": "Light carries information, mood, and credibility. Students learn to use available light responsibly and make basic lighting decisions without staging or distorting the story.", "children": [{"id": "a1cfedb0-21ed-4ecb-8350-afd20881d8e3", "type": "subtopic", "title": "Available light", "children": [{"id": "93f4d8d7-fe49-49ef-92e4-34aba999f6b1", "type": "concept", "title": "Direction"}, {"id": "abb9a09d-6128-4678-bee9-62a0c9923339", "type": "concept", "title": "Quality"}, {"id": "651d83b4-4ab2-420a-a8d5-321e3e322cb6", "type": "concept", "title": "Color temperature"}, {"id": "4101573f-1444-4731-a1f8-d7c76bd65983", "type": "concept", "title": "Mixed light"}], "description": "Students learn to read natural and artificial light in the field."}, {"id": "205c8ce6-3ab1-4471-a4f1-9f8213a5859c", "type": "subtopic", "title": "Basic lighting tools", "children": [{"id": "5d2e2dc7-3677-4964-a968-72da5f0c0996", "type": "concept", "title": "Reflectors"}, {"id": "e76654c7-7e9e-4c2b-9b4f-452bc3bf4b3f", "type": "concept", "title": "Window light"}, {"id": "a3de98c7-6eb8-4796-a874-2b10ce82e4aa", "type": "concept", "title": "On-camera flash limits"}, {"id": "9cd3e410-c263-43d6-8379-fef1a79e6701", "type": "concept", "title": "Small LED panels"}], "description": "Students learn practical options for portraits and controlled documentary situations."}, {"id": "798478e6-deab-4c52-a678-4dc4e0467dba", "type": "subtopic", "title": "Color and tonal judgment", "children": [{"id": "6eca87a5-a809-4cbc-9dd7-fa4c20e2821c", "type": "concept", "title": "White balance"}, {"id": "c679867e-8f74-4ed7-a98e-e5e8591af1b0", "type": "concept", "title": "Contrast"}, {"id": "c86ccc5c-f791-4fc1-8f0f-ff9d35a64d60", "type": "concept", "title": "Skin tones"}, {"id": "5295740c-53b0-4123-a8ad-6c894291d6f4", "type": "concept", "title": "Avoiding overprocessing"}], "description": "The point is to preserve realism while making images readable."}]}, {"id": "4b2deb16-56ee-47ca-b511-77fc2e13e8c4", "type": "topic", "title": "Shooting Events, Spot News, and Breaking News", "description": "Event and breaking-news work requires preparation, speed, safety, and editorial discipline. Students learn to cover what happened while resisting spectacle and misinformation.", "children": [{"id": "1edea6b4-c2cc-4de8-b2f1-33505ebd57b1", "type": "subtopic", "title": "Event coverage strategy", "children": [{"id": "c0385a11-f70e-4a54-a1dc-560499c74f6d", "type": "concept", "title": "Advance research"}, {"id": "abd1369b-d8cf-4244-a5b0-1cc4fbc326c8", "type": "concept", "title": "Shot lists"}, {"id": "15bc8ba0-7540-463e-8403-500bb2b54921", "type": "concept", "title": "Access points"}, {"id": "dcd0e0f1-e3f7-48bb-b5e1-636e9d756bb6", "type": "concept", "title": "Caption information"}], "description": "Students learn to arrive prepared and produce a complete visual report, not just isolated snapshots."}, {"id": "da2c7d2c-122b-43a8-b710-919ecec48d78", "type": "subtopic", "title": "Breaking-news fieldwork", "children": [{"id": "226e0d17-5a88-4303-80f3-3ebff980530c", "type": "concept", "title": "Scene assessment"}, {"id": "8432fde6-fd5f-4ff8-8059-c3bf1a6fd330", "type": "concept", "title": "Police/fire boundaries"}, {"id": "901e6d05-0f4c-4eeb-a7fd-f1dadc7dea6b", "type": "concept", "title": "Victim sensitivity"}, {"id": "bb0192df-e88b-44e5-9485-2c263cb693c8", "type": "concept", "title": "Transmission priorities"}], "description": "Students practice working quickly while protecting safety, accuracy, and dignity."}, {"id": "3ac37462-deb5-4b66-8cbc-31ad0f3be525", "type": "subtopic", "title": "Deadline filing", "children": [{"id": "c5cb10e6-e8b1-4768-b8b5-b5618344d5e8", "type": "concept", "title": "First selects"}, {"id": "e863a1fd-775b-4a36-baf1-e9cadb7f9c8b", "type": "concept", "title": "Caption basics"}, {"id": "7dfac42a-2e76-493a-9a1e-bafde79244a2", "type": "concept", "title": "File naming"}, {"id": "b9d3ad67-4ddb-4453-8514-5d2ffbfc5da3", "type": "concept", "title": "Editor communication"}], "description": "The goal is to select, caption, transmit, and update images on realistic news deadlines."}]}, {"id": "35e95b3c-a618-4db4-92da-f7dc74091858", "type": "topic", "title": "Portrait and Feature Photography", "description": "Portraits and features ask students to reveal character, place, and story through observed detail. This section balances rapport, consent, visual design, and journalistic honesty.", "children": [{"id": "2306b7db-ab28-49dc-8a8d-83b990707ba1", "type": "subtopic", "title": "Environmental portraits", "children": [{"id": "9cfdef8f-5be4-40b8-8c20-a8326a5d466b", "type": "concept", "title": "Location choice"}, {"id": "d128d8d3-85ab-4a3b-9c5f-ea2898dc436e", "type": "concept", "title": "Background control"}, {"id": "b25660c6-de31-4a78-9b11-a2f2f2f574c3", "type": "concept", "title": "Subject placement"}, {"id": "4a4d1fa7-7752-4096-80ba-971ac4947a07", "type": "concept", "title": "Relevant props"}], "description": "Students learn to photograph people in settings that add context and specificity."}, {"id": "ed09d6cf-0157-4e4e-9785-e8b8af58354d", "type": "subtopic", "title": "Feature moments", "children": [{"id": "e0278eb2-8961-41a9-92b3-83add9c17ffb", "type": "concept", "title": "Observation"}, {"id": "e49d54ab-896b-43f3-a749-4cdb5d84508a", "type": "concept", "title": "Patience"}, {"id": "16baec02-49f0-4a42-a863-cdf9fd29f900", "type": "concept", "title": "Human detail"}, {"id": "5332400b-329e-483f-a49d-788bd9381f55", "type": "concept", "title": "Sense of place"}], "description": "Students practice finding quieter visual stories in daily life, culture, work, and community."}, {"id": "c7c16ec8-3e26-4c52-8b28-adc2a0b3c0df", "type": "subtopic", "title": "Subject rapport", "children": [{"id": "45a9334f-718b-48f5-9a33-823cca721ac1", "type": "concept", "title": "Introductions"}, {"id": "4af43284-ff17-4176-ab4d-bdd6154f012a", "type": "concept", "title": "Consent"}, {"id": "4ab3c69b-6689-4229-b5af-0356c2bfe430", "type": "concept", "title": "Comfort and boundaries"}, {"id": "344aa2f5-f7cb-4b2c-9ad9-34f95351fdc9", "type": "concept", "title": "Minimal direction"}], "description": "The point is to build trust without directing subjects into false moments."}]}, {"id": "79ecf6cf-d76b-47af-a7b5-ec295ca56308", "type": "topic", "title": "Sports, Performance, and Action Photography", "description": "Fast-moving assignments teach anticipation, timing, and technical discipline. Students learn to photograph action while preserving story, emotion, and context.", "children": [{"id": "5c052aa1-0c8c-4c6b-aa68-c89447738ed3", "type": "subtopic", "title": "Action anticipation", "children": [{"id": "ca14bdc2-baa7-4a27-981f-0117d0ecdfd1", "type": "concept", "title": "Positioning"}, {"id": "57903545-2c44-4a7f-b204-3348ab991984", "type": "concept", "title": "Peak action"}, {"id": "e65fac52-f5e9-42a6-844d-b46a55ce4e03", "type": "concept", "title": "Reaction shots"}, {"id": "5f289e56-ddef-473c-8603-3ec57b1cb402", "type": "concept", "title": "Sequences"}], "description": "Students learn to read patterns and prepare before key moments happen."}, {"id": "65bb1ba8-af06-4ebe-9382-5eb31308fa4f", "type": "subtopic", "title": "Technical settings for motion", "children": [{"id": "e12b76b6-416c-4687-9741-318f2a05e238", "type": "concept", "title": "Fast shutter speeds"}, {"id": "405686b7-9bcb-494f-8a9a-08ac13e895a4", "type": "concept", "title": "Panning"}, {"id": "d88d4f90-378a-4045-893a-7e1bd0874408", "type": "concept", "title": "Continuous autofocus"}, {"id": "1d91b067-cf82-426b-8496-20319f2d6f17", "type": "concept", "title": "Long lenses"}], "description": "Students practice shutter, focus, and lens choices for action assignments."}, {"id": "7eac4934-35b5-4b80-90ce-7b0e52fac35d", "type": "subtopic", "title": "Story beyond the action", "children": [{"id": "e4f888b5-03c4-489f-b409-a7986cf8679c", "type": "concept", "title": "Crowd emotion"}, {"id": "c029095a-bb09-4820-80f4-a7e2821e3e07", "type": "concept", "title": "Coaches and families"}, {"id": "ff7201bf-85aa-445b-9850-9ace27c85201", "type": "concept", "title": "Preparation"}, {"id": "042cf22c-7534-41d1-9497-3762714109ec", "type": "concept", "title": "Aftermath"}], "description": "The goal is to capture stakes, atmosphere, and aftermath, not only the obvious play or performance."}]}, {"id": "8a483488-2bfd-471e-bb62-3c1bd5462328", "type": "topic", "title": "Mobile Photojournalism and Field Workflow", "description": "Modern photojournalists often work with phones, laptops, hotspots, and fast publishing systems. Students learn mobile tools without lowering standards.", "children": [{"id": "ad8809b4-ce83-4857-b7c6-904c7fe3561b", "type": "subtopic", "title": "Smartphone capture", "children": [{"id": "d31d485b-fb03-4d6f-8324-e7349c3e1780", "type": "concept", "title": "Exposure lock"}, {"id": "29a12987-0458-48f3-9944-5bd27da9c1d5", "type": "concept", "title": "Lens choices"}, {"id": "078b6768-2a7f-4b72-9692-eef1030de725", "type": "concept", "title": "Low-light limits"}, {"id": "37b3a707-d773-4d2c-b103-21957fa2c2a2", "type": "concept", "title": "Stabilization"}], "description": "Students learn when phones are appropriate and how to use them professionally."}, {"id": "ad7184b0-3369-443b-b08d-bbbcedb584ad", "type": "subtopic", "title": "Field editing and transmission", "children": [{"id": "e29f4071-bc5c-41da-ad31-4f3fbe92b83a", "type": "concept", "title": "Ingest"}, {"id": "010e29f7-74af-4fe2-a5db-7c13ffc206fc", "type": "concept", "title": "Metadata"}, {"id": "0ddb861a-89a5-4a00-8ec6-2b6c498bdb65", "type": "concept", "title": "Hotspots"}, {"id": "f4a78f4c-db1b-4232-9329-4279691dea33", "type": "concept", "title": "Cloud backup"}], "description": "Students practice fast, organized movement from camera to editor or CMS."}, {"id": "4ba195ed-3842-49f9-b661-8359a01c2d22", "type": "subtopic", "title": "Workflow reliability", "children": [{"id": "16189412-5a6b-4f38-acd1-969bbe9443cc", "type": "concept", "title": "Card management"}, {"id": "e4139619-e7ad-4cb5-9299-dfedc306eaf0", "type": "concept", "title": "Battery planning"}, {"id": "d607ecdb-ad4f-4af2-94d7-faa8a933bc4d", "type": "concept", "title": "Naming conventions"}, {"id": "a2e97d22-65da-4130-a2a1-97631ac9f628", "type": "concept", "title": "Redundant storage"}], "description": "The point is to prevent lost files, late files, and miscaptioned files under pressure."}]}, {"id": "a182fb78-2c2e-4d63-b6bd-fc1bf549351a", "type": "topic", "title": "Photo Editing, Toning, and Metadata", "description": "Editing in photojournalism means selecting, sequencing, toning, captioning, and preserving trust. Students learn what can be adjusted and what must never be altered.", "children": [{"id": "a3039b59-e4e2-4fe1-9f76-23036c1e50dc", "type": "subtopic", "title": "Selection and sequencing", "children": [{"id": "873fa7ab-b8d3-4ce8-bc15-38221470a943", "type": "concept", "title": "First edit"}, {"id": "26912836-2f44-456d-aa01-99cf88ba96a2", "type": "concept", "title": "Second edit"}, {"id": "07770f32-1985-4f95-9543-ad59732d3bd9", "type": "concept", "title": "Variety"}, {"id": "498c2ad6-ed7c-4a6b-bc19-92abdf9a9bd5", "type": "concept", "title": "Narrative order"}], "description": "Students learn to evaluate images for news value, visual strength, accuracy, and redundancy."}, {"id": "9f10c38b-54ac-4beb-aad2-33fc761ddc6b", "type": "subtopic", "title": "Ethical toning", "children": [{"id": "ff9cc996-476d-471a-b12e-9912d3446c5f", "type": "concept", "title": "Crop limits"}, {"id": "1a550fc4-c664-4658-bd43-27e3bf969792", "type": "concept", "title": "Exposure adjustment"}, {"id": "82554962-e765-4ea3-ac7c-b0ee619a0d54", "type": "concept", "title": "Color correction"}, {"id": "be126462-e73a-499d-a362-6502d5986747", "type": "concept", "title": "No adding/removing content"}], "description": "Students practice basic adjustments that improve readability without changing factual content."}, {"id": "400ec4d1-e499-4abf-840f-e67b61cac672", "type": "subtopic", "title": "Metadata and archive practice", "children": [{"id": "305a7ede-ab08-4efd-8b5d-31fe45aeb508", "type": "concept", "title": "IPTC fields"}, {"id": "76d55729-b695-465e-ad1e-d23d6dcbac47", "type": "concept", "title": "Creator credit"}, {"id": "d6418887-dbc7-40a5-9b8c-60f60ba19bb0", "type": "concept", "title": "Location"}, {"id": "66c94d7b-47fc-4654-8e89-19fe6cb8e4a3", "type": "concept", "title": "Keywords"}], "description": "The goal is to make images searchable, verifiable, and usable after deadline."}]}, {"id": "1cc571f4-3c87-43c1-bdce-1fd6bc4ec831", "type": "topic", "title": "Caption Writing and Visual Attribution", "description": "Captions are reporting, not labels. Students learn to identify people, explain action, provide context, and document what the image does and does not show.", "children": [{"id": "23ec2274-ccf3-4ac6-81b2-800c678384cf", "type": "subtopic", "title": "Caption fundamentals", "children": [{"id": "fb815ce2-d24b-4565-8f10-d3464e447425", "type": "concept", "title": "Who"}, {"id": "b939fe1b-12c0-4b58-a69e-519725e83341", "type": "concept", "title": "What"}, {"id": "de2079a2-0440-4044-81d9-aa30b984ec7a", "type": "concept", "title": "Where"}, {"id": "c024d9de-7cbd-437c-aa0e-de2c16adec33", "type": "concept", "title": "When"}, {"id": "82524eda-f24d-4708-8137-54baec63ed97", "type": "concept", "title": "Why it matters"}], "description": "Students practice the core information every news caption should answer."}, {"id": "d0e3c539-0e33-4d19-8542-4cb113b53cd5", "type": "subtopic", "title": "Accuracy and attribution", "children": [{"id": "13ae5bd6-9ee9-4f4e-8b73-beb3dd4cc373", "type": "concept", "title": "Name checks"}, {"id": "97b74f96-bc0c-4f11-9b1d-94906d80e082", "type": "concept", "title": "Source of information"}, {"id": "ad5bf9a2-fba6-493e-af0e-34b224a66dfa", "type": "concept", "title": "Quote attribution"}, {"id": "28e9519b-ffcb-4176-bde8-7e6b67b9aa23", "type": "concept", "title": "Unidentified subjects"}], "description": "Students learn to verify names, spellings, titles, ages, locations, and claims attached to photographs."}, {"id": "6598452d-bea7-49ad-8b74-ac555a4392d0", "type": "subtopic", "title": "Sensitive captions", "children": [{"id": "8bd19bdb-b4f0-470f-8694-2e1616b3aad8", "type": "concept", "title": "Victim identification"}, {"id": "f6f2ede4-2d7d-49b1-85f8-7eff7bacefb7", "type": "concept", "title": "Graphic content warnings"}, {"id": "89b4182e-fca9-4871-a5b6-56f07ce8609e", "type": "concept", "title": "Allegations"}, {"id": "b0328bec-6f9c-4e41-8d35-df442252d8a5", "type": "concept", "title": "Cultural context"}], "description": "The point is to avoid speculation, stigma, and harm when images involve trauma, crime, minors, or grief."}]}, {"id": "b0f94beb-32d9-4bae-b726-7f0252d21df5", "type": "topic", "title": "Photo Ethics, Consent, and Representation", "description": "Photojournalism has unusual ethical power because images feel immediate and persuasive. Students learn to make choices that preserve dignity, truth, and public interest.", "children": [{"id": "e358d4b8-ade3-4866-8be7-fbea01c12e5d", "type": "subtopic", "title": "Truthfulness and staging", "children": [{"id": "f42d28f8-98a7-4e42-ad9a-b0df73daf018", "type": "concept", "title": "No staging"}, {"id": "e311eb40-8a29-45a7-9688-33041b00423b", "type": "concept", "title": "No cloning"}, {"id": "1dae2d0a-6454-40fe-9606-d660f464aec2", "type": "concept", "title": "No misleading crops"}, {"id": "51fe6b01-0636-4582-868e-7baea96c5209", "type": "concept", "title": "Disclosure"}], "description": "Students learn why staging, reenactment, excessive direction, and manipulation undermine trust."}, {"id": "72abc35d-693c-4754-b150-02ba2939ab9d", "type": "subtopic", "title": "Consent and vulnerability", "children": [{"id": "3f4d44e3-0115-48ee-9d6e-dc2b2662f4cc", "type": "concept", "title": "Informed consent"}, {"id": "2d7abf5d-dd0b-46da-bc40-ddb96032f1a5", "type": "concept", "title": "Power dynamics"}, {"id": "e4349c6b-09ff-4bcc-ac40-0202bc864a1b", "type": "concept", "title": "Trauma awareness"}, {"id": "9fcc07e9-6f7e-4b02-88ee-16dd86b26dfd", "type": "concept", "title": "Public vs. private spaces"}], "description": "Students examine ethical practice with children, victims, patients, grieving families, and marginalized communities."}, {"id": "b365de3b-a0a7-4a60-b72e-d0bf5c732fea", "type": "subtopic", "title": "Representation and stereotypes", "children": [{"id": "3ef1ae50-789f-416f-8df4-b0b77cc88c59", "type": "concept", "title": "Visual cliches"}, {"id": "da937f1a-465b-4660-9580-c456cb533b6b", "type": "concept", "title": "Context"}, {"id": "845b1767-571d-4d8f-a708-a547bf584285", "type": "concept", "title": "Agency"}, {"id": "f26753e8-e1db-4de5-9943-4e9e04b5d402", "type": "concept", "title": "Diversity of frames"}], "description": "The goal is to avoid visual shortcuts that flatten people or communities."}]}, {"id": "0a88abd1-830d-4e60-bd83-d6a8832b2b29", "type": "topic", "title": "Visual Verification and Misinformation", "description": "Images can mislead through editing, context collapse, AI generation, or reuse. Students learn verification routines for both their own work and images found online.", "children": [{"id": "f61c7b82-8e42-465f-97ef-a5f98d45a3a0", "