values
  ('d6828b0b-954f-457b-a4d1-dda7586b59f4', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', null, 'topic'::public.curated_course_node_type, 'Camera Operation and Exposure', 'Photojournalists need technical control fast enough to disappear into the reporting. This section gives students command of camera settings so they can respond to real events without missing decisive moments.', 0),
  ('3026ef86-0aab-4793-ba95-ca7ace8e85c2', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'd6828b0b-954f-457b-a4d1-dda7586b59f4', 'subtopic'::public.curated_course_node_type, 'Exposure triangle', 'Students learn how aperture, shutter speed, and ISO work together to shape brightness, motion, depth, and noise.', 0),
