  ('9232b7bc-25f5-488f-9a2c-650e8ebbd3cd', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '44e1a9a0-89cc-4665-a25e-466ab83283dc', 'concept'::public.curated_course_node_type, 'Time and date settings', null, 3),
  ('61c780ef-308b-4a26-8eaf-725972338e63', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', null, 'topic'::public.curated_course_node_type, 'Composition for News Photos', 'Composition in photojournalism is not just beauty; it is clarity, evidence, hierarchy, and meaning. Students learn to organize the frame so audiences understand what matters and why.', 1),
