  ('bbf23aeb-d96e-496e-a14c-f176008099fe', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '26f24dfb-c4ee-48e1-aa4a-ae0d8147a9a3', 'concept'::public.curated_course_node_type, 'Establishing context', null, 0),
