values
  ('79ecf6cf-d76b-47af-a7b5-ec295ca56308', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', null, 'topic'::public.curated_course_node_type, 'Sports, Performance, and Action Photography', 'Fast-moving assignments teach anticipation, timing, and technical discipline. Students learn to photograph action while preserving story, emotion, and context.', 5),
