  ('1d91b067-cf82-426b-8496-20319f2d6f17', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '65bb1ba8-af06-4ebe-9382-5eb31308fa4f', 'concept'::public.curated_course_node_type, 'Long lenses', null, 3),
