  ('ff7201bf-85aa-445b-9850-9ace27c85201', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '7eac4934-35b5-4b80-90ce-7b0e52fac35d', 'concept'::public.curated_course_node_type, 'Preparation', null, 2),
  ('042cf22c-7534-41d1-9497-3762714109ec', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '7eac4934-35b5-4b80-90ce-7b0e52fac35d', 'concept'::public.curated_course_node_type, 'Aftermath', null, 3),
  ('8a483488-2bfd-471e-bb62-3c1bd5462328', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', null, 'topic'::public.curated_course_node_type, 'Mobile Photojournalism and Field Workflow', 'Modern photojournalists often work with phones, laptops, hotspots, and fast publishing systems. Students learn mobile tools without lowering standards.', 6),
  ('ad8809b4-ce83-4857-b7c6-904c7fe3561b', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '8a483488-2bfd-471e-bb62-3c1bd5462328', 'subtopic'::public.curated_course_node_type, 'Smartphone capture', 'Students learn when phones are appropriate and how to use them professionally.', 0),
