  ('ad7184b0-3369-443b-b08d-bbbcedb584ad', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '8a483488-2bfd-471e-bb62-3c1bd5462328', 'subtopic'::public.curated_course_node_type, 'Field editing and transmission', 'Students practice fast, organized movement from camera to editor or CMS.', 1),
  ('e29f4071-bc5c-41da-ad31-4f3fbe92b83a', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'ad7184b0-3369-443b-b08d-bbbcedb584ad', 'concept'::public.curated_course_node_type, 'Ingest', null, 0),
