  ('a182fb78-2c2e-4d63-b6bd-fc1bf549351a', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', null, 'topic'::public.curated_course_node_type, 'Photo Editing, Toning, and Metadata', 'Editing in photojournalism means selecting, sequencing, toning, captioning, and preserving trust. Students learn what can be adjusted and what must never be altered.', 7),
