  ('d0e3c539-0e33-4d19-8542-4cb113b53cd5', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '1cc571f4-3c87-43c1-bdce-1fd6bc4ec831', 'subtopic'::public.curated_course_node_type, 'Accuracy and attribution', 'Students learn to verify names, spellings, titles, ages, locations, and claims attached to photographs.', 1),
