  ('ad5bf9a2-fba6-493e-af0e-34b224a66dfa', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'd0e3c539-0e33-4d19-8542-4cb113b53cd5', 'concept'::public.curated_course_node_type, 'Quote attribution', null, 2),
  ('28e9519b-ffcb-4176-bde8-7e6b67b9aa23', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'd0e3c539-0e33-4d19-8542-4cb113b53cd5', 'concept'::public.curated_course_node_type, 'Unidentified subjects', null, 3),
  ('6598452d-bea7-49ad-8b74-ac555a4392d0', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '1cc571f4-3c87-43c1-bdce-1fd6bc4ec831', 'subtopic'::public.curated_course_node_type, 'Sensitive captions', 'The point is to avoid speculation, stigma, and harm when images involve trauma, crime, minors, or grief.', 2),
  ('8bd19bdb-b4f0-470f-8694-2e1616b3aad8', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '6598452d-bea7-49ad-8b74-ac555a4392d0', 'concept'::public.curated_course_node_type, 'Victim identification', null, 0),
  ('f6f2ede4-2d7d-49b1-85f8-7eff7bacefb7', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '6598452d-bea7-49ad-8b74-ac555a4392d0', 'concept'::public.curated_course_node_type, 'Graphic content warnings', null, 1),
  ('89b4182e-fca9-4871-a5b6-56f07ce8609e', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '6598452d-bea7-49ad-8b74-ac555a4392d0', 'concept'::public.curated_course_node_type, 'Allegations', null, 2),
  ('b0328bec-6f9c-4e41-8d35-df442252d8a5', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '6598452d-bea7-49ad-8b74-ac555a4392d0', 'concept'::public.curated_course_node_type, 'Cultural context', null, 3),
  ('b0f94beb-32d9-4bae-b726-7f0252d21df5', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', null, 'topic'::public.curated_course_node_type, 'Photo Ethics, Consent, and Representation', 'Photojournalism has unusual ethical power because images feel immediate and persuasive. Students learn to make choices that preserve dignity, truth, and public interest.', 9),
  ('e358d4b8-ade3-4866-8be7-fbea01c12e5d', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'b0f94beb-32d9-4bae-b726-7f0252d21df5', 'subtopic'::public.curated_course_node_type, 'Truthfulness and staging', 'Students learn why staging, reenactment, excessive direction, and manipulation undermine trust.', 0),
  ('f42d28f8-98a7-4e42-ad9a-b0df73daf018', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'e358d4b8-ade3-4866-8be7-fbea01c12e5d', 'concept'::public.curated_course_node_type, 'No staging', null, 0),
  ('e311eb40-8a29-45a7-9688-33041b00423b', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'e358d4b8-ade3-4866-8be7-fbea01c12e5d', 'concept'::public.curated_course_node_type, 'No cloning', null, 1),
