  ('51fe6b01-0636-4582-868e-7baea96c5209', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'e358d4b8-ade3-4866-8be7-fbea01c12e5d', 'concept'::public.curated_course_node_type, 'Disclosure', null, 3),
  ('72abc35d-693c-4754-b150-02ba2939ab9d', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'b0f94beb-32d9-4bae-b726-7f0252d21df5', 'subtopic'::public.curated_course_node_type, 'Consent and vulnerability', 'Students examine ethical practice with children, victims, patients, grieving families, and marginalized communities.', 1),
  ('3f4d44e3-0115-48ee-9d6e-dc2b2662f4cc', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '72abc35d-693c-4754-b150-02ba2939ab9d', 'concept'::public.curated_course_node_type, 'Informed consent', null, 0),
  ('2d7abf5d-dd0b-46da-bc40-ddb96032f1a5', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '72abc35d-693c-4754-b150-02ba2939ab9d', 'concept'::public.curated_course_node_type, 'Power dynamics', null, 1),
