  ('9fcc07e9-6f7e-4b02-88ee-16dd86b26dfd', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '72abc35d-693c-4754-b150-02ba2939ab9d', 'concept'::public.curated_course_node_type, 'Public vs. private spaces', null, 3),
