  ('3ef1ae50-789f-416f-8df4-b0b77cc88c59', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'b365de3b-a0a7-4a60-b72e-d0bf5c732fea', 'concept'::public.curated_course_node_type, 'Visual cliches', null, 0),
