  ('f26753e8-e1db-4de5-9943-4e9e04b5d402', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'b365de3b-a0a7-4a60-b72e-d0bf5c732fea', 'concept'::public.curated_course_node_type, 'Diversity of frames', null, 3),
  ('0a88abd1-830d-4e60-bd83-d6a8832b2b29', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', null, 'topic'::public.curated_course_node_type, 'Visual Verification and Misinformation', 'Images can mislead through editing, context collapse, AI generation, or reuse. Students learn verification routines for both their own work and images found online.', 10),
