  ('9f162fef-0bee-478c-bc17-e2bd4c29b775', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'b6d9c8ee-5b3e-4000-8852-ec62776c4c89', 'concept'::public.curated_course_node_type, 'Screenshots', null, 2),
