  ('17cbeca5-969d-4b3d-a637-0ac74b02bf3a', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '0c234fda-a74c-4048-9f46-b8e7e25df77a', 'concept'::public.curated_course_node_type, 'Generated images', null, 0),
