  ('ced5b14e-3087-4ad2-8e65-cfe86f71caa9', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '0c234fda-a74c-4048-9f46-b8e7e25df77a', 'concept'::public.curated_course_node_type, 'Manipulation detection', null, 2),
  ('b73b22f9-7350-4f96-b0bf-459164793b9b', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '0c234fda-a74c-4048-9f46-b8e7e25df77a', 'concept'::public.curated_course_node_type, 'Labeling policies', null, 3),
  ('bc8ac76c-6333-4f1e-b74e-bc09686b14f5', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', null, 'topic'::public.curated_course_node_type, 'Picture Stories and Photo Essays', 'A picture story requires sustained reporting, access, sequencing, and narrative shape. Students learn to move beyond single images into coherent visual journalism.', 11),
  ('25a036a7-c3e8-4351-b7b3-4793e0d1004e', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'bc8ac76c-6333-4f1e-b74e-bc09686b14f5', 'subtopic'::public.curated_course_node_type, 'Story development', 'Students learn to pitch visual stories with reporting questions, access plans, and ethical considerations.', 0),
  ('77c0b9db-cd84-40a9-8135-6f9a7b1176d3', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '25a036a7-c3e8-4351-b7b3-4793e0d1004e', 'concept'::public.curated_course_node_type, 'Story focus', null, 0),
