  ('125650ed-708e-4380-9e70-cfe70561f957', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '25a036a7-c3e8-4351-b7b3-4793e0d1004e', 'concept'::public.curated_course_node_type, 'Reporting plan', null, 3),
  ('2681c05a-e700-4aa2-9c6b-ed9972de0b4c', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', 'bc8ac76c-6333-4f1e-b74e-bc09686b14f5', 'subtopic'::public.curated_course_node_type, 'Visual variety', 'Students build essays with enough range to sustain attention and understanding.', 1),
  ('b830b74b-3dd3-4f8a-abd0-fab7be048394', 'b0c1d2e3-4f5a-4b26-9c56-6d7e8f9a0b76', '2681c05a-e700-4aa2-9c6b-ed9972de0b4c', 'concept'::public.curated_course_node_type, 'Wide shots', null, 0),
